stem:
Um servidor responde com status 404 a uma requisição. O que acontece com a Promise do `fetch` no código abaixo?

```js
const resposta = await fetch(url);
console.log(resposta.ok, resposta.status);
```

params.code:
import http from 'node:http';
const srv = http.createServer((req, res) => { res.writeHead(404, {}); res.end('{"x":1}'); });
await new Promise((r) => srv.listen(0, '127.0.0.1', r));
const base = 'http://127.0.0.1:' + srv.address().port;
try { const resposta = await fetch(base + '/x'); console.log('resolveu', resposta.ok, resposta.status); } catch (e) { console.log('rejeitou', e.name); }
srv.close();

import http from 'node:http';
const srv = http.createServer((req, res) => { res.writeHead(200, {}); res.end('{"x":1}'); });
await new Promise((r) => srv.listen(0, '127.0.0.1', r));
const base = 'http://127.0.0.1:' + srv.address().port;
const r = await fetch(base + '/x'); const p = r.json(); console.log(p instanceof Promise, typeof (await p));
srv.close();

